	byte[] encryptPkcs1(final byte[] message) {
		int k = (this.n.bitLength() + 7) / 8;
		if (message.length > k - 11) {
			throw new IllegalArgumentException("RSA message too long for modulus");
		}
		byte[] em = new byte[k];
		em[0] = 0x00;
		em[1] = 0x02;
		int psEnd = k - message.length - 1;
		for (int i = 2; i < psEnd; i++) {
			int b;
			do {
				b = RANDOM.nextInt(256);
			} while (b == 0);
			em[i] = (byte) b;
		}
		em[psEnd] = 0x00;
		System.arraycopy(message, 0, em, psEnd + 1, message.length);
		byte[] c = new BigInteger(1, em).modPow(this.e, this.n).toByteArray();
		if (c.length == k) {
			return c;
		}
		byte[] out = new byte[k];
		if (c.length > k) {
			System.arraycopy(c, c.length - k, out, 0, k);
		} else {
			System.arraycopy(c, 0, out, k - c.length, c.length);
		}
		return out;
	}

