private static final class Der {
	final byte[] der;
	int pos;

	Der(final byte[] der) {
		this.der = der;
	}

	int u8() {
		return this.der[this.pos++] & 0xff;
	}

	void expect(final int tag) {
		int got = this.u8();
		if (got != tag) {
			throw new IllegalArgumentException("DER tag " + tag + " got " + got);
		}
	}

	int readLen() {
		int b = this.u8();
		if (b < 0x80) {
			return b;
		}
		int n = b & 0x7f;
		int len = 0;
		while (n-- > 0) {
			len = len << 8 | this.u8();
		}
		return len;
	}

	void skip(final int n) {
		this.pos += n;
	}

	BigInteger readInt() {
		this.expect(0x02);
		int len = this.readLen();
		byte[] v = new byte[len];
		System.arraycopy(this.der, this.pos, v, 0, len);
		this.pos += len;
		return new BigInteger(1, v);
	}
}
